void BuildlogTable(int n) {
    for (int i = 0; i <= n; i++)
        log[1 << i] = i;  // 预存 2^i 对应的指数 i
}
int query(int n) {
    return log[lowbit(n)];  // lowbit 提取最低位1，查表得位置
